% DrawCircuit — coordinates in cm; SVG Y axis inverted.
\definecolor{dcColor0}{HTML}{171a20}
\definecolor{dcColor1}{HTML}{2463cb}
\definecolor{dcColor2}{HTML}{df4949}
\begin{circuitikz}[european resistors, american inductors, american ports, line cap=round, line join=round]
\ctikzset{bipoles/length=1.4cm}
\draw[draw=dcColor0, line width=1.4226pt] (5.5,0);
\draw[draw=dcColor0, line width=1.4226pt] (-3.5,0) -- (-1,0);
% Component: resistor
\draw[draw=dcColor0, line width=1.4226pt] (-5.5,0) to[R, fill=white, name=dcComponent0] (-3.5,0);
% Component: capacitor
\draw[draw=dcColor0, line width=1.4226pt] (-1,0) to[C, fill=white, name=dcComponent1] (1,0);
% Component: inductor
\draw[draw=dcColor0, line width=1.4226pt] (3.5,0) to[L, fill=white, name=dcComponent2] (5.5,0);
% Component: resistor
\draw[draw=dcColor0, line width=1.4226pt] (5.5,0) to[R, fill=white, name=dcComponent3] (7.5,0);
\fill[dcColor0] (0,3.5) circle (3.2009pt);
\node[text=dcColor1, anchor=center, inner sep=0pt, rotate=0, font=\fontsize{15.649}{20.3437}\selectfont] at (-4.5,0.75) {$R_{AB}$};
\node[text=dcColor1, anchor=center, inner sep=0pt, rotate=0, font=\fontsize{15.649}{20.3437}\selectfont] at (0,0.75) {$C_1 = 10 \mu F$};
\node[text=dcColor1, anchor=center, inner sep=0pt, rotate=0, font=\fontsize{15.649}{20.3437}\selectfont] at (4.5,0.75) {$L_1 = 220 \mu H$};
\node[text=dcColor1, anchor=center, inner sep=0pt, rotate=0, font=\fontsize{15.649}{20.3437}\selectfont] at (6.5,0.75) {$50 \Omega$};
\node[text=dcColor2, anchor=center, inner sep=0pt, rotate=0, font=\fontsize{17.0717}{22.1931}\selectfont] at (0,4.1) {$V_{out}$};
\node[text=dcColor2, anchor=west, inner sep=0pt, rotate=0, font=\fontsize{17.0717}{22.1931}\selectfont] at (0,-2.5) {$I_1 = \frac{V}{R}$};
\node[text=dcColor2, anchor=west, inner sep=0pt, rotate=0, font=\fontsize{17.0717}{22.1931}\selectfont] at (-4.5,-2.5) {Testo normale};
\end{circuitikz}

